#!/bin/sh
# Code generated by AI (Claude Sonnet 5.5)

# Installs a package as root with the host package manager, a '-' name skips that package manager.
#
# Arguments:
#   $1  Package name for apt.
#   $2  Package name for dnf.
#   $3  Package name for pacman.
#
# Returns:
#   1 when sudo refuses, the install fails or no supported package manager exists.
pkg_install() {
  if pkg_installed "$@"; then
    return 0
  fi

  if command -v apt-get >/dev/null 2>&1; then
    sudo_run apt-get update || return 1
    sudo_run apt-get install -y "$1"
  elif command -v dnf >/dev/null 2>&1; then
    sudo_run dnf install -y "$2"
  elif command -v pacman >/dev/null 2>&1; then
    sudo_run pacman -S --needed --noconfirm "$3"
  else
    return 1
  fi
}

# Checks a package is installed with the host package manager, a '-' name counts as installed.
#
# Arguments:
#   $1  Package name for apt.
#   $2  Package name for dnf.
#   $3  Package name for pacman.
#
# Returns:
#   1 when the package is missing or no supported package manager exists.
pkg_installed() {
  if command -v apt-get >/dev/null 2>&1; then
    [ "$1" = "-" ] || [ "$(dpkg-query -W -f='${Status}' "$1" 2>/dev/null)" = "install ok installed" ]
  elif command -v dnf >/dev/null 2>&1; then
    [ "$2" = "-" ] || rpm -q "$2" >/dev/null 2>&1
  elif command -v pacman >/dev/null 2>&1; then
    [ "$3" = "-" ] || pacman -Q "$3" >/dev/null 2>&1
  else
    return 1
  fi
}
